arguments.command:
cat << 'EOF' > /tmp/stackalloc_nint.cs
using System;

var span = (stackalloc nint[4]);
span[0] = 10;
span[1] = 20;
span[2] = 30;
span[3] = 40;

nint sum = 0;
foreach (var val in span)
    sum += val;

Console.WriteLine($"Span<nint> length: {span.Length}");
Console.WriteLine($"Sum: {sum}");
Console.WriteLine($"Element size (nint): {nint.Size} bytes");
EOF
dotnet run --project /tmp/stackalloc_nint.cs 2>&1 || dotnet-script /tmp/stackalloc_nint.cs 2>&1 || (cd /tmp && dotnet new console -n NintTest --force -o NintTest && cp stackalloc_nint.cs NintTest/Program.cs && dotnet run --project NintTest)

